import numpy as np
def equation(eps, T, params):
    p = params
    base = p[0] + p[1]*T + p[2]/T
    sq = (p[3] + p[4]*T + p[5]/T)*np.sqrt(eps)
    return base + sq + p[6]*eps**2 + p[7]*np.exp(-eps)*np.sqrt(T) + p[8]*eps**3/T + p[9]*np.log(eps)
